// bisectRight: return the rightmost insertion point for val in a sorted array.
// If val equals an element, the insertion point is AFTER that element.
// key: function to extract comparison value from each array element.

golden_completion:
function bisectRight<T>(arr: T[], val: number, key: (x: T) => number): number {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (key(arr[mid]) <= val) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

